<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../api'
import AssignmentEditor from './AssignmentEditor.vue'
import QuestionAnswer from './QuestionAnswer.vue'
const props=defineProps({course:Object,staff:Boolean}),exams=ref([]),exam=ref(null),editing=ref(false),editInitial=ref(null),own=ref(null),answers=ref({}),results=ref([]),view=ref('exam'),sort=ref('score'),error=ref(''),busy=ref(false)
const base=`/courses/${props.course.id}/exams`
async function load(){exams.value=await api(base)}
async function run(action){busy.value=true;error.value='';try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function create(input){await run(async()=>{const saved=await api(editInitial.value?`${base}/${editInitial.value.id}`:base,{method:editInitial.value?'PUT':'POST',body:input});editing.value=false;editInitial.value=null;await load();exam.value=await api(`${base}/${saved.id}`)})}
async function open(id){await run(async()=>{view.value='exam';exam.value=await api(`${base}/${id}`);own.value=null;answers.value={};results.value=[];if(props.staff)await ranking();else if(!exam.value.isPractice){own.value=await api(`${base}/${id}/attempt`);answers.value={...own.value.answers}}})}
async function transition(action){if(!confirm(action==='publish'?'發布後題目鎖定，確定發布？':'確定關閉考試？'))return;await run(async()=>{await api(`${base}/${exam.value.id}/${action}`,{method:'POST'});await load();exam.value=await api(`${base}/${exam.value.id}`)})}
async function save(submit){if(submit&&!confirm('提交後不能修改，確定提交考試？'))return;await run(async()=>{await api(`${base}/${exam.value.id}/attempt`,{method:'PUT',body:{expectedVersion:own.value.version,answers:answers.value,submit}});own.value=await api(`${base}/${exam.value.id}/attempt`)})}
async function ranking(){results.value=await api(`${base}/${exam.value.id}/results?sort=${sort.value}`)}
async function grade(item){await run(async()=>{await api(`${base}/${exam.value.id}/results/${item.id}`,{method:'PUT',body:{score:item.score,feedback:item.feedback,expectedVersion:item.version}});await ranking()})}
function display(q,text){if(q.questionType==='essay')return text;try{return JSON.parse(text || '[]').map(n=>q.options[n]).join('、')}catch{return text}}
onMounted(()=>run(load))
</script>
<template><section class="surface form-surface"><h2>考試管理</h2><p class="muted">獨立考試、一次提交，教師／助教人工評分（滿分 100）。成績儲存後學生本人可見。</p><p v-if="error" class="error-box" role="alert">{{error}}</p><button v-if="staff && course.status!=='archived'" class="button primary" @click="editInitial=null;editing=!editing">建立考試</button><AssignmentEditor exam v-if="editing" :initial="editInitial" :course-id="course.id" :busy="busy" @save="create" @cancel="editing=false" /><div v-for="item in exams" :key="item.id" class="question-editor"><button class="text-button" :disabled="busy" @click="open(item.id)">{{item.title}}</button> · {{ {draft:'草稿',published:'已發布',closed:'已關閉'}[item.status] }}</div><template v-if="exam"><hr /><h3>{{exam.title}}</h3><nav v-if="staff" class="course-navigation" aria-label="考試功能"><button class="button secondary" :class="{active:view==='exam'}" @click="view='exam'">題目與評閱</button><button class="button secondary" :class="{active:view==='ranking'}" @click="view='ranking';run(ranking)">排行榜</button></nav><div v-show="view==='exam'"><p style="white-space:pre-wrap">{{exam.instructions}}</p><p>開放：{{exam.opensAt?new Date(exam.opensAt).toLocaleString():'未限制'}} · 截止：{{exam.dueAt?new Date(exam.dueAt).toLocaleString():'未限制'}}</p><button v-if="staff && exam.status==='draft'" class="button secondary" :disabled="busy" @click="editInitial=exam;editing=true">編輯考試草稿</button><button v-if="staff && exam.status==='draft'" class="button primary" :disabled="busy" @click="transition('publish')">發布考試</button><button v-if="staff && exam.status==='published'" class="button secondary" :disabled="busy" @click="transition('close')">關閉考試</button><p v-if="exam.isPractice" class="submission-notice">學生體驗模式可閱讀已開放題目；考試作答須由學生本人登入。</p><article v-for="q in exam.questions" :key="q.id" class="question-editor"><h3>題目 {{Number(q.id)+1}}</h3><p>{{q.promptText}}</p><p v-if="staff && q.questionType!=='essay'">標準答案：{{q.standardAnswer.map(n=>q.options[n]).join('、')}}</p><QuestionAnswer v-if="!staff && own" :question="q" v-model="answers[q.id]" :disabled="busy || !!own.submittedAt || exam.status!=='published'" /></article><p v-if="!exam.questions.length" class="muted">尚未到開放時間。</p><template v-if="own"><p v-if="own.submittedAt">已提交 · 成績 {{own.score ?? '待評分'}} / 100 · {{own.feedback}}</p><div v-else><button class="button secondary" :disabled="busy || exam.status!=='published'" @click="save(false)">儲存考試草稿</button><button class="button primary" :disabled="busy || exam.status!=='published'" @click="save(true)">提交考試</button></div></template></div><section v-if="staff && view==='ranking'"><h3>排行榜</h3><label>排序<select aria-label="排行榜排序" v-model="sort" @change="run(ranking)"><option value="score">名次排序</option><option value="student">學號排序</option></select></label><div class="table-scroll"><table class="data-table"><thead><tr><th>名次</th><th>學號</th><th>姓名</th><th>得分</th></tr></thead><tbody><tr v-for="item in results" :key="item.id"><td>{{item.rank ?? '待評分'}}</td><td>{{item.studentNumber || '未填學號'}}</td><td>{{item.studentName}}</td><td>{{item.score ?? '待評分'}}</td></tr></tbody></table></div><p class="field-hint">同分並列名次，未評分不列名次。僅教師／助教可查看完整排行榜。</p></section><template v-if="staff && view==='exam'"><h3>評閱與登分</h3><label>排序<select v-model="sort" @change="run(ranking)"><option value="student">學號排序</option><option value="score">成績由高至低</option></select></label><p class="field-hint">未評分排最後；同分並列名次。未填學號排在有學號者之後。</p><article v-for="item in results" :key="item.id" class="question-editor"><h3>{{item.studentNumber || '未填學號'}} · {{item.studentName}} · 名次 {{item.rank ?? '待評分'}}</h3><div v-for="q in exam.questions" :key="q.id"><strong>{{q.promptText}}</strong><p style="white-space:pre-wrap">{{display(q,item.answers[q.id])}}</p></div><form @submit.prevent="grade(item)"><label>成績<input type="number" min="0" max="100" step="0.01" v-model.number="item.score" required /></label><label>評語<textarea v-model="item.feedback" maxlength="16000"></textarea></label><button class="button primary" :disabled="busy">儲存成績</button></form></article></template></template></section></template>
